                expect(merged['sys_hub_flow']).toBeDefined()
                expect(merged['sys_hub_flow'].length).toBe(1)

                const flow = merged['sys_hub_flow'][0]
                expect(flow.name).toBe('Example_2_Subflow_CreateOutage')
                expect(flow.description).toBe('All combinations for Complex Objects')
                expect(flow.type).toBe('subflow')
                expect(flow.run_as).toBe('user')
                expect(flow.sys_id).toBe('8165047fb11ef6d0f8774074995d9957')
                expect(flow.generation_source).toBe('fluent')
